import { cn } from "@/lib/utils";

import { PORTRAIT_PATHS, PORTRAIT_SIZE } from "./portrait-pixels";

/**
 * Pixel-art portrait of Desi (PRD 3: "a pixel-art avatar derived from" her
 * photo; generated by scripts/generate-portrait.mjs). Inline SVG, not an image
 * file, so the hero has no raster image and the H1 stays the LCP element
 * (FR-HERO-02). crispEdges keeps the pixels square at any size.
 */
function PixelPortrait({ className }: { className?: string }) {
  return (
    <svg
      role="img"
      aria-label="Pixel-art portrait of Desi Armanda Sari"
      viewBox={`0 0 ${PORTRAIT_SIZE} ${PORTRAIT_SIZE}`}
      shapeRendering="crispEdges"
      className={cn("block", className)}
    >
      {PORTRAIT_PATHS.map((p) => (
        <path key={p.fill} fill={p.fill} d={p.d} />
      ))}
    </svg>
  );
}

export { PixelPortrait };
